707	// Grace window for a SIGTERM'd child to flush and exit before we force SIGKILL.
708	const GRACEFUL_KILL_TIMEOUT_MS = 3000;
709	
710	/**
711	 * Gracefully terminate a pty's child process: send SIGTERM so it can flush and
712	 * exit cleanly, then escalate to SIGKILL only if it overstays the grace window.
713	 * Resolves once the process is gone (or was already dead).
714	 *
715	 * node-pty's bare `kill()` sends SIGHUP, which Claude Code does not trap — so
716	 * its in-memory session tail (the last several turns) was lost on every
717	 * refresh/quit, and no `--resume`/`--continue` could recover what never
718	 * reached the jsonl. SIGTERM + a wait gives Claude the chance to persist first.
719	 */
720	type KillableProc = {
721	  kill: (signal?: string) => void;
722	  onExit: (listener: (e: { exitCode: number; signal?: number }) => void) => {
723	    dispose: () => void;
724	  };
725	};
726	
727	function gracefulKillProc(proc: KillableProc, timeoutMs = GRACEFUL_KILL_TIMEOUT_MS): Promise<void> {
728	  return new Promise<void>((resolve) => {
729	    let settled = false;
730	    let timer: ReturnType<typeof setTimeout> | null = null;
731	    let disposable: { dispose: () => void } | null = null;
732	    const finish = () => {
733	      if (settled) return;
734	      settled = true;
735	      if (timer) clearTimeout(timer);
736	      try {
737	        disposable?.dispose();
738	      } catch {
739	        // listener already gone
740	      }
741	      resolve();
742	    };
743	    try {
744	      disposable = proc.onExit(() => finish());
745	    } catch {
746	      // proc doesn't expose onExit (already disposed) — rely on the timer/catch.
747	    }
748	    timer = setTimeout(() => {
749	      try {
750	        proc.kill('SIGKILL');
751	      } catch {
752	        // already dead
753	      }
754	      finish();
755	    }, timeoutMs);
756	    try {
757	      proc.kill('SIGTERM');
758	    } catch {
759	      // already dead — nothing to wait for
760	      finish();
761	    }
762	  });
763	}
764	
765	/** Detach a record from all registries and persist its mirror (shared by the
766	 *  kill paths). The map delete makes the spawn-time onExit handler a no-op. */
767	function teardownRecord(id: string, record: PtyRecord): void {
768	  ptys.delete(id);
769	  activityMonitor.unregister(id);
770	  remoteControlService.unregister(id);
771	  contextUsageService.unregister(id);
772	  // Persist before killing — restart() relies on the snapshot for visual
773	  // context when it respawns into the same id.
774	  persistAndDisposeMirror(id, record);
775	}
776	
777	function killPtyInternal(id: string): Promise<void> {
778	  const record = ptys.get(id);
779	  if (!record) return Promise.resolve();
780	  teardownRecord(id, record);
781	  return gracefulKillProc(record.proc);
782	}
783	
784	/**
785	 * Kill a specific PTY (graceful: SIGTERM → grace → SIGKILL). Fire-and-forget;
786	 * callers that must serialize a respawn against the dying process use
787	 * killPtyAwait instead.
788	 */
789	export function killPty(id: string): void {
790	  void killPtyInternal(id);
791	}
792	
793	/**
794	 * Kill a specific PTY and resolve once it has actually exited (or the grace
795	 * window elapsed). The renderer's reattach/restart paths await this before
796	 * respawning so the new `claude --resume` process never races the dying one
797	 * for the session jsonl (a brief two-writer overlap could corrupt the tail).
798	 */
799	export function killPtyAwait(id: string): Promise<void> {
800	  return killPtyInternal(id);
801	}
802	
803	/**
804	 * Kill all PTYs (on app quit). Awaits every child's graceful exit in parallel
805	 * so the bound is ~one grace window, not the sum — the before-quit handler
806	 * awaits this so the app doesn't exit before Claude flushes its session.
807	 */
808	export async function killAll(): Promise<void> {
809	  const pending: Promise<void>[] = [];
810	  for (const [id, record] of ptys) {
811	    persistAndDisposeMirror(id, record);
812	    pending.push(gracefulKillProc(record.proc));
813	  }
814	  ptys.clear();
815	  // Bulk cleanup — don't rely on onExit during shutdown
816	  activityMonitor.stop();
817	  await Promise.all(pending);
818	}
819	
820	/**
821	 * Kill all PTYs owned by a specific WebContents (on window close).
822	 * Fire-and-forget graceful kills — the app stays alive (macOS) so there's no
823	 * exit to race, but the child still gets its SIGTERM flush window.
824	 */
825	export function killByOwner(owner: WebContents): void {
826	  for (const [id, record] of ptys) {
827	    if (record.owner === owner) {
828	      teardownRecord(id, record);
829	      void gracefulKillProc(record.proc);
830	    }
831	  }
832	}
833	
834	/**
835	 * Return all PTY ids attached to `taskId`, optionally filtered by kind /
836	 * featureId. Used by SessionRegistry.restartAllForTask to find the right set
837	 * without string-prefix matching on PTY ids — which would accidentally hit
838	 * future task-bound PTYs (e.g. the ports TUI).
839	 */
840	export function listForTask(
841	  taskId: string,
842	  opts?: { kinds?: PtyKind[]; featureId?: string },
843	): string[] {
844	  const result: string[] = [];
845	  for (const [id, rec] of ptys) {
846	    if (rec.taskId !== taskId) continue;
847	    if (opts?.kinds && !opts.kinds.includes(rec.kind)) continue;
848	    if (opts?.featureId && rec.featureId !== opts.featureId) continue;
849	    result.push(id);
850	  }
851	  return result;
852	}
853	
854	/**
855	 * Spawn an arbitrary command in a PTY tagged as kind='tui'. Used by feature
856	 * orchestrators (e.g. ports onboarding) to host a side-car interactive
857	 * program inside the existing drawer tab UI without polluting agent/shell
858	 * code paths.
859	 */
860	export async function startCommandPty(options: {
861	  id: string;
862	  command: string;
863	  args: string[];
864	  cwd: string;
865	  cols: number;
866	  rows: number;
867	  env?: Record<string, string>;
868	  owner: WebContents | null;
869	  taskId: string;
870	  featureId: string;
871	  /** PTY registry kind. Side-car TUIs (default) vs user-facing service runs. */
872	  kind?: 'tui' | 'service';
873	  /**
874	   * Fires only when the process exits on its own — an explicit killPty()
875	   * removes the record first, so the guarded handler below never reaches it.
876	   * Callers that kill notify themselves; this hook covers self-death.
877	   */
878	  onExit?: (info: { exitCode: number; signal?: number }) => void;
879	}): Promise<{ reattached: boolean }> {
880	  const existing = ptys.get(options.id);
881	  if (existing) {
882	    existing.owner = options.owner;
883	    return { reattached: true };
884	  }
885	
886	  const pty = getPty();
887	  const proc = pty.spawn(options.command, options.args, {
888	    name: 'xterm-256color',
889	    cols: options.cols,
890	    rows: options.rows,
891	    cwd: options.cwd,
892	    env: { ...process.env, ...(options.env ?? {}) } as Record<string, string>,
893	  });
894	
895	  const record: PtyRecord = {
896	    proc,
897	    cwd: options.cwd,
898	    isDirectSpawn: false,
899	    owner: options.owner,
900	    kind: options.kind ?? 'tui',
901	    taskId: options.taskId,
902	    featureId: options.featureId,
903	    mirror: new TerminalMirror(options.cols, options.rows),
904	  };
905	
906	  ptys.set(options.id, record);
907	
908	  proc.onData((data: string) => {
909	    // The mirror always consumes — output emitted before any renderer
910	    // attaches (service startup banners) is recovered from its serialized
911	    // state on reattach.
912	    record.mirror?.write(data);
913	    if (record.owner && !record.owner.isDestroyed()) {
914	      record.owner.send(`pty:data:${options.id}`, data);
915	    }
916	  });
917	
918	  proc.onExit(({ exitCode, signal }: { exitCode: number; signal?: number }) => {
919	    if (ptys.get(options.id) !== record) return;
920	    if (record.owner && !record.owner.isDestroyed()) {
921	      record.owner.send(`pty:exit:${options.id}`, { exitCode, signal });
922	    }
923	    persistAndDisposeMirror(options.id, record);
924	    ptys.delete(options.id);
925	    options.onExit?.({ exitCode, signal });
926	  });
927	
928	  return { reattached: false };
929	}
