289	  private async loadGpuAddon() {
290	    // Shell-only sessions render transparent (allowTransparency: true, theme
291	    // background rgba(0,0,0,0)) so the floating right-pane glass shows through.
292	    // xterm 6's WebGL renderer paints a transparent background as solid black,
293	    // so use the built-in DOM renderer for these — it composites alpha
294	    // correctly. (Opaque main terminals keep WebGL for output performance.)
295	    if (this.shellOnly) return; // built-in DOM renderer — alpha-correct
296	
297	    // xterm 6 removed the canvas renderer; the choices are WebGL or xterm's
298	    // built-in DOM renderer. On Linux, WebGL has had compositing bugs that
299	    // blank the terminal on content updates (typing, output), so we use the
300	    // DOM renderer there. NOTE: the DOM renderer historically clips the last
301	    // glyph of full rows — re-verify on Linux under the current Chromium.
302	    const isLinux = navigator.userAgent.includes('Linux');
303	    if (isLinux) return; // built-in DOM renderer
304	
305	    try {
306	      const { WebglAddon } = await import('@xterm/addon-webgl');
307	      const webgl = new WebglAddon();
308	      webgl.onContextLoss(() => {
309	        webgl.dispose();
310	        void this.loadGpuAddon();
311	      });
312	      this.terminal.loadAddon(webgl);
313	    } catch (err) {
314	      // A GPU-renderer failure drops to xterm's DOM renderer; log it so that
315	      // regression is visible, not mysterious.
316	      console.warn('[terminal] WebGL renderer failed, using DOM renderer:', err);
317	    }
318	  }
