807	  /**
808	   * Columns/rows that fill the padded content box — like FitAddon's
809	   * proposeDimensions, but WITHOUT subtracting a fixed scrollbar reserve.
810	   * FitAddon reserves `viewport.scrollBarWidth` (~15-19px) on the right for a
811	   * scrollbar we hide entirely (and that Claude's NO_FLICKER mode never uses),
812	   * which left the grid short of the right edge — a lopsided gutter. We measure
813	   * the same cell size FitAddon uses and divide the `.xterm` element's real
814	   * content box (clientWidth, which already subtracts any actual scrollbar) by
815	   * it. Falls back to FitAddon if xterm's internal render metrics ever move.
816	   */
817	  private proposeDims(): { cols: number; rows: number } | undefined {
818	    const el = this.terminal.element;
819	    const cell = (
820	      this.terminal as unknown as {
821	        _core?: {
822	          _renderService?: { dimensions?: { css?: { cell?: { width: number; height: number } } } };
823	        };
824	      }
825	    )._core?._renderService?.dimensions?.css?.cell;
826	    if (!el || !cell?.width || !cell?.height) {
827	      return this.fitAddon.proposeDimensions();
828	    }
829	    // Measure the `.xterm` element's OWN content box via clientWidth/Height
830	    // (not the parent's computed width): clientWidth subtracts any ancestor
831	    // scrollbar that the element doesn't actually get to paint into, whereas
832	    // getComputedStyle().width does not. Using the parent width over-measured
833	    // by the scrollbar's ~16px, handing out columns that don't fit — invisible
834	    // under WebGL (it clips) but a visible right-edge overlap under the DOM
835	    // renderer. clientWidth already includes padding, so subtract it back out.
836	    const es = window.getComputedStyle(el);
837	    const availW =
838	      el.clientWidth -
839	      (parseInt(es.getPropertyValue('padding-left')) +
840	        parseInt(es.getPropertyValue('padding-right')));
841	    const availH =
842	      el.clientHeight -
843	      (parseInt(es.getPropertyValue('padding-top')) +
844	        parseInt(es.getPropertyValue('padding-bottom')));
845	    // A hidden / not-yet-laid-out element has clientWidth/Height 0, so availW/H
846	    // go non-positive. Bail to undefined so the resize is skipped (rather than
847	    // shipping a squashed grid) until the layout settles.
848	    if (!Number.isFinite(availW) || !Number.isFinite(availH) || availW <= 0 || availH <= 0) {
849	      return undefined;
850	    }
851	    // Shell-only (DOM renderer) lays glyphs wider than `cell.width`; once we've
852	    // measured the real advance, size columns against it so the grid fits.
853	    const colWidth = this.shellOnly && this.domCellWidth ? this.domCellWidth : cell.width;
854	    return {
855	      cols: Math.max(2, Math.floor(availW / colWidth)),
856	      rows: Math.max(1, Math.floor(availH / cell.height)),
857	    };
858	  }
