860	  /**
861	   * Read the DOM renderer's actual per-column advance from a rendered row and
862	   * cache it in `domCellWidth`. xterm's reported `css.cell.width` under-counts
863	   * the real glyph advance, so rows render wider than the grid xterm sizes and
864	   * the last glyph spills past the right padding. When the measured advance
865	   * changes the answer, re-fit once so the corrected column count takes effect;
866	   * a stable measurement (within 0.05px) is a no-op, so this converges. No-op
867	   * for WebGL terminals, whose grid is pixel-snapped to the cell.
868	   */
869	  private measureDomCellWidth(): void {
870	    if (!this.shellOnly) return;
871	    const el = this.terminal.element;
872	    requestAnimationFrame(() => {
873	      const row = el?.querySelector('.xterm-rows > div') as HTMLElement | null;
874	      const renderedCols = this.terminal.cols;
875	      if (!row || renderedCols <= 0) return;
876	      const advance = row.scrollWidth / renderedCols;
877	      // Ignore bogus reads during layout transitions (collapsed/empty rows).
878	      if (!Number.isFinite(advance) || advance <= 0) return;
879	      const prev = this.domCellWidth;
880	      if (prev !== undefined && Math.abs(prev - advance) < 0.05) return;
881	      this.domCellWidth = advance;
882	      this.fit();
883	    });
